// Checks of the shared library of the tools. Run as `tools_test [file.bb | directory]...`: Every file given (and every .bb
// in a directory) has to survive a trip through the tokenizer unchanged.
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <vector>
#include <stdexcept>
#include "config.hpp"
#include "diff.hpp"
#include "edits.hpp"
#include "files.hpp"
#include "keywords.hpp"
#include "tokens.hpp"

using namespace blitz::tools;

static int failures = 0;

#define CHECK(expr)                                                                     \
	do {                                                                                \
		if (!(expr)) {                                                                  \
			std::fprintf(stderr, "%s:%d: failed: %s\n", __FILE__, __LINE__, #expr);     \
			failures++;                                                                 \
		}                                                                               \
	} while (0)

static std::string kinds(std::string const& source)
{
	std::string out;
	for (auto const& t : tokenize(source)) {
		switch (t.type) {
		case kind::word:      out += 'w'; break;
		case kind::number:    out += 'n'; break;
		case kind::string:    out += 's'; break;
		case kind::comment:   out += 'c'; break;
		case kind::symbol:    out += 'y'; break;
		case kind::separator: out += ':'; break;
		case kind::newline:   out += '\n'; break;
		case kind::space:     out += '_'; break;
		case kind::other:     out += 'o'; break;
		}
	}
	return out;
}

static void test_tokens()
{
	CHECK(kinds("a%=1.5;x") == "wync");
	CHECK(kinds("Print \"hi\" ; c") == "w_s_c");
	CHECK(kinds("x=>y") == "wyw");                 // => is one symbol
	CHECK(tokenize("x=>y")[1].text == "=>");        // and keeps its spelling
	CHECK(kinds("a$ $FF") == "w_n");                // a$ is a name, $FF a number
	CHECK(kinds("a:b") == "w:w");
	CHECK(kinds("\"open") == "s");                  // A string may end with the line
	CHECK(join(tokenize("a\r\nb\rc\n")) == "a\r\nb\rc\n");
	CHECK(tokenize("a\r\nb")[1].text == "\r\n");
	CHECK(kinds(".5 0xFF 0b11 %101 1.") == "n_n_n_n_n");
	CHECK(lower("EndIf") == "endif");
}

static void test_keywords()
{
	CHECK(keyword_spelling("ENDIF") == "EndIf");
	CHECK(keyword_spelling("wend") == "Wend");
	CHECK(keyword_spelling("ENDSELECT") == "EndSelect");
	CHECK(keyword_spelling("endfunction") == "EndFunction");
	CHECK(keyword_spelling("Print").empty());
	CHECK(keyword_spelling("Zzz").empty());
	CHECK(keyword_spelling("Abs") == "Abs");
	CHECK(keyword_takes_value("return"));
	CHECK(!keyword_takes_value("wend"));
	CHECK(keyword_is_function("int"));
}

static void test_config()
{
	auto a = parse_config("# comment\nIndent-Style = space\n; also\nindent_width=2\nname = \"quoted\"\n", "test");
	CHECK(a.size() == 3);
	CHECK(a[0].first == "indent_style" && a[0].second == "space");
	CHECK(a[1].second == "2");
	CHECK(a[2].second == "quoted");

	auto j = parse_config("{ \"indent-style\": \"tab\", \"indent_width\": 8, \"final_newline\": false }", "test");
	CHECK(j.size() == 3);
	CHECK(j[0].first == "indent_style" && j[0].second == "tab");
	CHECK(j[1].second == "8");
	CHECK(j[2].second == "false");
	CHECK(parse_config("{}", "test").empty());
	CHECK(parse_config("", "test").empty());

	for (const char* bad : { "no equals sign", "{ \"a\": [1] }", "{ \"a\": 1", "{ \"a\" 1 }", "= 1" }) {
		bool threw = false;
		try {
			parse_config(bad, "test");
		} catch (std::runtime_error const&) {
			threw = true;
		}
		CHECK(threw);
	}

	// The nearest file wins, searching upwards.
	auto root = std::filesystem::temp_directory_path() / "blitz_tools_test_config";
	std::filesystem::remove_all(root);
	std::filesystem::create_directories(root / "a" / "b");
	write_file(root / "blitz-format.json", "{}");
	write_file(root / "a" / ".blitz-format", "x = 1");
	auto inner = find_config(root / "a" / "b", { ".blitz-format", "blitz-format.json" });
	CHECK(inner && (*inner == (root / "a" / ".blitz-format").lexically_normal()));
	auto outer = find_config(root, { ".blitz-format", "blitz-format.json" });
	CHECK(outer && (*outer == (root / "blitz-format.json").lexically_normal()));
	CHECK(!find_config(root / "a" / "b", { ".blitz-nothing-like-this" }));
	std::filesystem::remove_all(root);
}

static void test_edits()
{
	std::string text = "ab\ncd\r\nef";
	CHECK(offset_of(text, 1, 1) == 0);
	CHECK(offset_of(text, 2, 2) == 4);
	CHECK(offset_of(text, 3, 1) == 7);
	CHECK(offset_of(text, 2, 99) == 5); // Clamped to the end of the line
	CHECK(offset_of(text, 99, 1) == text.size());

	CHECK(apply_edits(text, { { 0, 2, "X" }, { 7, 9, "Y" } }) == "X\ncd\r\nY");
	CHECK(apply_edits(text, { { 7, 9, "Y" }, { 0, 2, "X" } }) == "X\ncd\r\nY"); // Any order
	CHECK(apply_edits("abc", { { 1, 1, "1" }, { 1, 1, "2" } }) == "a12bc");       // Inserts keep their order
	CHECK(apply_edits("abc", { { 0, 1, "x" }, { 1, 2, "y" } }) == "xyc");         // Touching is fine
	CHECK(apply_edits(text, { make_edit(text, 2, 1, 2, 3, "--") }) == "ab\n--\r\nef");

	std::string error;
	CHECK(!check_edits("abc", { { 0, 2, "" }, { 1, 3, "" } }, error));
	CHECK(!error.empty());
	CHECK(!check_edits("abc", { { 2, 9, "" } }, error));
	bool threw = false;
	try {
		apply_edits("abc", { { 0, 2, "" }, { 1, 3, "" } });
	} catch (std::runtime_error const&) {
		threw = true;
	}
	CHECK(threw);
}

static void test_sources()
{
	auto root = std::filesystem::temp_directory_path() / "blitz_tools_test_sources";
	std::filesystem::remove_all(root);
	std::filesystem::create_directories(root / "sub" / "deep");
	for (const char* name : { "a.bb", "sub/B.B3D", "sub/c.bp", "sub/d.txt", "sub/deep/e.Bb", "f.bbx" }) {
		write_file(root / name, "");
	}
	auto found = find_sources(root);
	CHECK(found.size() == 2 && found[0] == root / "a.bb" && found[1] == root / "sub" / "deep" / "e.Bb"); // Only .bb: .b3d is a model format as well
	bool threw = false;
	try {
		find_sources(root / "missing");
	} catch (std::runtime_error const&) {
		threw = true;
	}
	CHECK(threw);
	std::filesystem::remove_all(root);
}

static void test_diff()
{
	CHECK(unified_diff("a\nb\n", "a\nb\n", "x", "y").empty());
	std::string d = unified_diff("a\nb\nc\n", "a\nB\nc\n", "x", "y");
	CHECK(d == "--- x\n+++ y\n@@ -1,3 +1,3 @@\n a\n-b\n+B\n c\n");
	d = unified_diff("a\n", "a\nb\n", "x", "y");
	CHECK(d == "--- x\n+++ y\n@@ -1,1 +1,2 @@\n a\n+b\n");
	d = unified_diff("", "a\n", "x", "y");
	CHECK(d == "--- x\n+++ y\n@@ -0,0 +1,1 @@\n+a\n");

	// Two changes far apart are two hunks.
	std::string before, after;
	for (int i = 0; i < 30; i++) {
		before += std::to_string(i) + "\n";
		after += ((i == 2) || (i == 27)) ? "changed\n" : std::to_string(i) + "\n";
	}
	d = unified_diff(before, after, "x", "y");
	size_t hunks = 0;
	for (size_t at = d.find("@@ -"); at != std::string::npos; at = d.find("@@ -", at + 1)) {
		hunks++;
	}
	CHECK(hunks == 2);
}

int main(int argc, char** argv)
{
	test_tokens();
	test_keywords();
	test_config();
	test_edits();
	test_sources();
	test_diff();

	for (int i = 1; i < argc; i++) {
		std::vector<std::filesystem::path> files;
		if (std::filesystem::is_directory(argv[i])) {
			for (auto const& entry : std::filesystem::recursive_directory_iterator(argv[i])) {
				if (entry.is_regular_file() && (entry.path().extension() == ".bb")) {
					files.push_back(entry.path());
				}
			}
		} else {
			files.push_back(argv[i]);
		}
		for (auto const& file : files) {
			std::string source = read_file(file);
			if (join(tokenize(source)) != source) {
				std::fprintf(stderr, "%s: the tokens do not join back to the source\n", file.generic_string().c_str());
				failures++;
			}
		}
	}
	if (failures == 0) {
		std::printf("ok\n");
	}
	return failures ? 1 : 0;
}
